<?php
namespace App\Controllers;
use Config\Database;
final class VerificationMonitoringController extends BaseController { public function index():string{$db=Database::connect();$result=(string)$this->request->getGet('result');$date=(string)$this->request->getGet('date');$base=$db->table('verification_logs');if(in_array($result,['verified','not_enrolled','student_not_found','invalid_request','unauthorized'],true))$base->where('verification_result',$result);if(preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$date))$base->where('DATE(requested_at)',$date);$pager=service('pager');$page=max(1,(int)$this->request->getGet('page'));$total=(clone $base)->countAllResults();$logs=$base->orderBy('requested_at','DESC')->orderBy('id','DESC')->limit(25,($page-1)*25)->get()->getResultArray();$all=$db->table('verification_logs');return view('verifications/index',['title'=>'Verification monitoring','logs'=>$logs,'result'=>$result,'date'=>$date,'total'=>$all->countAllResults(),'successful'=>$db->table('verification_logs')->where('verification_result','verified')->countAllResults(),'unsuccessful'=>$db->table('verification_logs')->where('verification_result !=','verified')->countAllResults(),'pager'=>$pager->makeLinks($page,25,$total)]);}}
